// Original decorative movement illustrations; the linked professional videos teach form.
export function movementArt(type){
  const skin='#a66e4e',shirt='#718b53',pants='#243d31',shoe='#172b23';
  const line=(d,color,w=15)=>`<path d="${d}" fill="none" stroke="${color}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
  const head=(x,y)=>`<circle cx="${x}" cy="${y}" r="13" fill="${skin}"/><path d="M${x-12} ${y-4}q0-16 13-11q14 1 12 13q-8-9-25-2" fill="#28352c"/>`;
  let body='';
  if(type==='chair')body=`<path d="M80 137v61m0-47h42v47M78 133h50" fill="none" stroke="#9ead87" stroke-width="5" stroke-linecap="round"/>${line('M124 139 L159 151 L155 193',pants,19)}${line('M109 139 L137 154 L132 193',pants,17)}${line('M115 91 L109 139',shirt,31)}${line('M119 96 L152 112 L172 102',skin,10)}${head(121,67)}${line('M151 198h21',shoe,9)}${line('M129 198h19',shoe,9)}`;
  else if(type==='wall')body=`<path d="M191 33v173" stroke="#b4c39e" stroke-width="5"/><path d="M199 33v173" stroke="#d0dabe" stroke-width="2"/>${line('M109 145 L87 194',pants,20)}${line('M120 146 L106 195',pants,18)}${line('M141 99 L115 147',shirt,32)}${line('M146 96 L164 115 L188 95',skin,11)}${head(154,75)}${line('M82 198h23',shoe,9)}${line('M105 198h21',shoe,9)}`;
  else if(type==='bridge')body=`<rect x="20" y="204" width="223" height="7" rx="3" fill="#c1cfaa"/>${head(56,190)}${line('M80 177 L128 145',shirt,28)}${line('M132 146 L164 123 L196 194',pants,20)}${line('M79 178 L100 196 L134 198',skin,10)}${line('M191 200h20',shoe,9)}`;
  else if(type==='bird')body=`<rect x="15" y="204" width="230" height="7" rx="3" fill="#c1cfaa"/>${line('M89 121 L52 112 L24 110',pants,18)}${line('M93 126 L91 179 L67 197',pants,18)}${line('M103 123 L152 126',shirt,28)}${line('M153 130 L151 191',skin,11)}${line('M151 122 L198 120 L228 116',skin,10)}${head(179,124)}${line('M57 199h21',shoe,9)}`;
  else if(type==='deadbug')body=`<rect x="18" y="204" width="220" height="7" rx="3" fill="#c1cfaa"/>${head(55,191)}${line('M81 185 L134 185',shirt,28)}${line('M132 183 L156 136 L195 151',pants,18)}${line('M132 186 L176 190 L214 199',pants,16)}${line('M83 178 L60 126 L44 103',skin,10)}${line('M91 177 L115 143 L125 113',skin,10)}`;
  else body=`${line('M127 136 L131 172 L136 198',pants,20)}${line('M114 139 L91 156 L62 153',pants,19)}${line('M120 91 L120 135',shirt,32)}${line('M110 94 L86 119 L69 102',skin,11)}${line('M135 98 L154 111 L171 90',skin,10)}${head(121,64)}${line('M132 203h22',shoe,9)}${line('M55 151v18',shoe,9)}`;
  return `<svg class="movement" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 230" aria-hidden="true"><ellipse cx="133" cy="215" rx="94" ry="6" fill="#d3dfc2"/>${body}</svg>`;
}
